('proposta_inst_titulo','Institucional · título','text','proposta','"We are technology, we are Selbetti!"',420,'Slide 2'),
('proposta_inst_texto','Institucional · texto','text','proposta',to_jsonb('Acreditamos no poder da tecnologia para transformar empresas, processos e pessoas. A Selbetti nasceu em 1977 com o propósito de integrar tecnologia para resolver desafios reais, com foco em inovação, eficiência e resultados.'||chr(10)||'Hoje, somos reconhecidos como a maior One-Stop-Tech brasileira, com um portfólio completo que vai da gestão eficiente de impressão e dispositivos de TI à implementação de projetos complexos de cibersegurança, inteligência artificial e experiências físicas e digitais para o cliente.'::text),421,'Slide 2, um parágrafo por linha'),
('proposta_inst_numeros','Institucional · números','text','a_confirmar',to_jsonb('2.5k|colaboradores'||chr(10)||'+45|aquisições estratégicas'||chr(10)||'10|unidades de negócio'::text),422,'Três linhas valor|rótulo'),
('proposta_inst_destaque','Institucional · destaque','text','a_confirmar','"QUASE|50|anos de experiência em tecnologia"',423,'prefixo|número|rótulo'),
('proposta_inst_chamada','Institucional · chamada','text','proposta','"Transforme suas operações de TI em um motor estratégico de crescimento e inovação."',424,'Slide 3'),
('proposta_inst_ciclo','Institucional · ciclo','text','proposta','"Entregamos um ciclo evolutivo completo e contínuo, unindo as disciplinas de Cloud, Datacenter, Observabilidade e ITO para garantir resiliência, segurança, eficiência operacional e previsibilidade financeira em ambientes híbridos e complexos."',425,'Slide 4'),
('proposta_inst_ciclo2','Institucional · abordagem','text','proposta','"Nossa abordagem integrada, suportada por automação inteligente e consultoria especializada 24x7, assegura a modernização da infraestrutura e das aplicações, reduzindo custos e riscos, e elevando a confiabilidade do negócio."',426,'Slide 4'),
('proposta_fechamento_chamada','Fechamento · chamada','text','proposta','"Vamos conversar sobre como podemos transformar o seu negócio?"',427,'Slide 12'),
('proposta_oferta_subtitulo','Subtítulo da oferta','text','decisao','"Alocação de Profissionais"',430,NULL),
